import unittest
from solution import solve

class Acceptance(unittest.TestCase):
    def test_empty(self): self.assertEqual(solve([0,10], []), [[0,10]])
    def test_full(self): self.assertEqual(solve([0,10], [[-2,12]]), [])
    def test_overlap(self): self.assertEqual(solve([0,10], [[2,5],[4,7]]), [[0,2],[7,10]])
    def test_touch(self): self.assertEqual(solve([0,10], [[1,3],[3,6]]), [[0,1],[6,10]])
    def test_clip(self): self.assertEqual(solve([0,10], [[-2,2],[8,14]]), [[2,8]])
    def test_outside(self): self.assertEqual(solve([0,10], [[-5,-2],[12,20]]), [[0,10]])
    def test_zero(self): self.assertEqual(solve([0,10], [[3,3]]), [[0,10]])
    def test_window_zero(self): self.assertEqual(solve([5,5], [[0,10]]), [])
    def test_unsorted(self): self.assertEqual(solve([0,10], [[7,8],[2,3]]), [[0,2],[3,7],[8,10]])
    def test_invalid(self):
        for busy in ([[9,2]], [[False,2]], [[1]], [['1',2]], [[20,11]]):
            with self.subTest(busy=busy), self.assertRaises(ValueError): solve([0,10], busy)
    def test_unchanged(self):
        data=[[7,8],[2,3]]; solve([0,10],data); self.assertEqual(data,[[7,8],[2,3]])

if __name__ == "__main__": unittest.main()
